advanced.code:
var x = 0
func bump(_ a: inout Int, _ b: inout Int) {
    a += 1
    b += 1
}

// bump(&x, &x) // overlapping access error

actor Counter {
    var value = 0
    func next() async -> Int {
        let old = value
        await Task.yield()
        value = old + 1
        return value
    }
}

let data = Data([1, 2, 3, 4])
let sum = data.withUnsafeBytes { raw -> UInt8 in
    raw.bindMemory(to: UInt8.self).reduce(0, +)
}
print(sum)

protocol P { func required() }
extension P { func helper() { print("ext") } }
struct S: P {
  func required() { print("req") }
  func helper() { print("S") }
}
let p: any P = S()
p.helper()   // ext

try await withThrowingTaskGroup(of: Int.self) { group in
  for i in 0..<3 { group.addTask { try await work(i) } }
  var sum = 0
  do {
    for try await v in group { sum += v }
    return sum
  } catch {
    group.cancelAll()
    throw error
  }
}
